import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync,writeFileSync,readFileSync,readdirSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {randomUUID} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {DatabaseSync} from 'node:sqlite';
import {RecordStore,SourcePolicy,LearningBudget,acquireLearningLease,releaseLearningLease,digest,CapabilityError,type PluginContext,type SourceRef} from '@friend-pi/core';
import {ExpertController,blockedByFrozenScope,peekExpertLearningJob,type ExpertLearningJob,type FrozenRun} from '../src/index.js';
import type {EvidenceRef} from '../src/skills.js';

function fixture(){
 const dir=mkdtempSync(join(tmpdir(),'friend-skills-v1-')),controller=new ExpertController(dir),entries:{entryId:string;customType:string;data:any}[]=[],sourceText='CSV import failed because the encoding and required column names were not checked.',source:SourceRef={sessionId:'s',entryId:'source',start:0,end:sourceText.length,hash:digest(sourceText)},policy=new SourcePolicy(controller.store),lease=acquireLearningLease(controller.store,randomUUID())!;
 let calls=0,admit=true;
 const ctx:PluginContext={origin:'user',dataDir:dir,projectDir:dir,projectId:'p',sessionId:'s',runId:'run-1',modelId:'fake/fixed',thinkingLevel:'off',executionMode:'single',policy:{v:1,revision:1,runId:'run-1',stage:'settled',canSwitchRole:true,unsettledTools:0,tools:['read','write','edit','bash','friend_expert'],writeScopes:['.'],executionMode:'single',planMode:false},isIdle:()=>true,history:()=>[{id:'source',type:'message',role:'user',text:sourceText,parentId:null,timestamp:'2026-10-10'}],readSource:ref=>{assert.equal(ref.sessionId,'s');assert.equal(ref.entryId,'source');return {id:'source',type:'message',role:'user',text:sourceText,parentId:null,timestamp:'2026-10-10'};},readCheck:ref=>policy.readCheck(ref,'p'),complete:async()=>{calls++;return JSON.stringify({title:'CSV preflight',description:'Check CSV before import',applicability:'CSV import',exclusions:['other formats'],keywords:['CSV','导入'],body:'Before importing CSV, verify its encoding and required column names; stop on objective errors.'});},request:async()=>{throw Error('Memory is unavailable');},emit:()=>{},notify:()=>{},appendEntry:(customType,data)=>{const entry={entryId:randomUUID(),customType,data};entries.push(entry);return entry.entryId;},findJournalEntry:operationId=>entries.find(e=>e.data.operationId===operationId)};
 const evidence:EvidenceRef[]=[{kind:'pi',projectId:'p',source}];
 function bind(job:ExpertLearningJob){ctx.learning={budgetId:job.budgetId,sourceRunId:job.sourceRunId,lease,canAdmit:()=>admit};ctx.modelId=job.modelId;ctx.thinkingLevel=job.thinkingLevel;}
 async function step(id:string){const job=controller.store.get<ExpertLearningJob>(`job:${id}`)!.value;bind(job);return (await controller.executeLearningJob(id,ctx,{lease,budgetId:job.budgetId})).job;}
 async function drain(id:string,max=30){let job=controller.store.get<ExpertLearningJob>(`job:${id}`)!.value;for(let i=0;i<max&&['queued','retryable'].includes(job.state);i++)job=await step(id);return job;}
 async function submit(extra:Record<string,unknown>={}){return await controller.dispatch('candidate.submit',{key:randomUUID(),skillBody:{title:'CSV preflight',description:'编码与列名预检查',keywords:['CSV','导入','编码'],applicability:'CSV import',exclusions:['non-CSV'],body:'Verify CSV encoding and required column names before import.'},evidence,...extra},ctx) as {id:string;revision:number};}
 async function trial(id:string,revision:number){return await controller.dispatch('trial.configure',{id,expectedRevision:revision,scope:{projectId:'p',applicability:'CSV import'},limits:{maxTasks:3},key:randomUUID()},ctx) as {revision:number};}
 function attribution(runId:string){return {v:1,decisionEntryId:randomUUID(),adoptions:entries.filter(e=>e.customType==='friend-pi.expert.adoption'&&e.data.runId===runId&&e.data.skills.some((s:any)=>s.statusAtFreeze==='trial')).map(e=>({operationId:e.data.operationId,journalEntryId:e.entryId,skillsHash:digest(e.data.skills)}))};}
 function check(passed=true,producerRunId='run-1',taskId='task-1'){const ref={checkId:randomUUID(),version:1,hash:digest({passed}),taskId,producerRunId,artifacts:[]};policy.registerCheck({ref,projectId:'p',passed,output:{exitCode:passed?0:1,trialAttribution:attribution(producerRunId)},sources:[source]});return {kind:'check' as const,projectId:'p',check:ref};}
 function manifest(id:string){const candidate=controller.skillCatalog.head(id,ctx),skill=controller.skillCatalog.version(id,candidate.version,ctx),baseline=controller.skillCatalog.version('seed.implementer.1',1,ctx);const cases=(phase:string)=>[{id:`${phase}-a`,kind:'positive',input:`${phase} scenario alpha with encoding`,expected:{ok:true},families:[`${phase}-encoding`],critical:true},{id:`${phase}-b`,kind:'positive',input:`${phase} scenario beta with required columns`,expected:{ok:true},families:[`${phase}-columns`],critical:true},{id:`${phase}-outside`,kind:'negative',input:`${phase} outside scope number ${phase==='release'?'seven':'four'}`,expected:{ok:true},families:[`${phase}-outside`],critical:true}];return {candidateId:id,candidateHash:skill.contentHash,baseline:{id:baseline.id,version:baseline.version,hash:baseline.contentHash},trainFamilies:['source-task'],validation:cases('validation'),release:cases('release'),modelId:'fake/fixed',thinkingLevel:'off',provider:'fake',tools:[],timeoutMs:1000,maxCalls:12,environmentHash:digest('fixture-env'),checkerHash:digest('strict-json'),promptHash:digest('frozen-text-prompt')};}
 async function validation(id:string,change?:(value:ReturnType<typeof manifest>)=>void){const value=manifest(id);change?.(value);const saved=await controller.dispatch('validation.manifest',{key:randomUUID(),manifest:value},ctx) as {manifestHash:string};return await controller.dispatch('validation.schedule',{id,expectedRevision:controller.skillCatalog.head(id,ctx).revision,manifestHash:saved.manifestHash},ctx) as {jobId:string};}
 return {dir,controller,ctx,entries,evidence,source,policy,lease,submit,trial,step,drain,check,attribution,manifest,validation,calls:()=>calls,admit:(value:boolean)=>{admit=value;},close:()=>{releaseLearningLease(controller.store,lease);controller.dispose();rmSync(dir,{recursive:true,force:true});}};
}

test('E01/E02/E23: nineteen seed Skills, separate roles, bounded metadata search and Chinese project isolation',async()=>{const f=fixture();try{const s=f.controller.snapshot(f.ctx);assert.equal(s.skills.length,19);assert.equal(s.skillExperts.length,5);assert.equal(s.roles.length,5);assert.ok(s.skills.every(v=>v.head.validationKind==='seed-acceptance'&&!('body' in v)));const hits=await f.controller.dispatch('catalog.search',{query:'需求'},f.ctx) as {items:{id:string;body?:unknown}[]};assert.ok(hits.items.some(v=>v.id==='seed.reviewer.1'));assert.ok(hits.items.every(v=>v.body===undefined));await assert.rejects(f.controller.dispatch('catalog.search',{limit:'8'},f.ctx),/整数/);const a=await f.submit();await f.trial(a.id,a.revision);assert.ok(f.controller.skillCatalog.search({query:'编码'},f.ctx).items.some(v=>v.id===a.id));assert.ok(!f.controller.skillCatalog.search({query:'编码'},{...f.ctx,projectId:'other'}).items.some(v=>v.id===a.id));assert.equal(f.controller.freeze({},f.ctx).selectionMode,'auto');assert.ok(!f.controller.freeze({},f.ctx).prompt.includes('Verify CSV encoding'));}finally{f.close();}});

test('E07/E08/E11/E12: strict boundaries, candidate idempotence and immutable CAS versions',async()=>{const f=fixture();try{for(const extra of [{modelId:'other/model'},{budgetId:'new'},{script:'run.sh'}])await assert.rejects(f.submit(extra),/不得设置/);await assert.rejects(f.submit({skillBody:{title:'script',applicability:'CSV import',body:'```bash\nrm file\n```'}}),/文本方法/);const input={key:'same',skillBody:{title:'a',applicability:'CSV import',body:'Read data carefully.'},evidence:f.evidence};const a=await f.controller.dispatch('candidate.submit',input,f.ctx) as {id:string;revision:number};assert.deepEqual(await f.controller.dispatch('candidate.submit',input,f.ctx),a);await assert.rejects(f.controller.dispatch('candidate.submit',{...input,skillBody:{...input.skillBody,body:'different'}},f.ctx),/幂等/);const edit=await f.controller.dispatch('skill.update',{id:a.id,expectedRevision:a.revision,body:'Check encoding first.',key:'edit'},f.ctx) as {version:number;revision:number};assert.equal(edit.version,2);await assert.rejects(f.controller.dispatch('skill.update',{id:a.id,expectedRevision:a.revision,body:'stale',key:'stale'},f.ctx),/revision/);assert.equal((await f.controller.dispatch('skill.read',{id:a.id,version:1},f.ctx) as {body:string}).body,'Read data carefully.');const rollback=await f.controller.dispatch('skill.rollback',{id:a.id,expectedRevision:edit.revision,targetVersion:1,key:'rollback'},f.ctx) as {version:number};assert.equal(rollback.version,3);}finally{f.close();}});

test('E03/E04/E05/E06/E21: actual canonical adoption freezes body, intersects scopes and respects explicit selection',async()=>{const f=fixture();try{const a=await f.submit({skillBody:{title:'CSV preflight',applicability:'CSV import',body:'Verify CSV encoding and required column names before import.',restrictions:{tools:['read','write'],writeScopes:['src']}}});await f.trial(a.id,a.revision);const run=f.controller.beginRun(f.ctx),request={expertId:'implementer',runId:run.runId,catalogHash:run.hash,skillIds:[a.id]};const adopted=await f.controller.dispatch('use',request,{...f.ctx,origin:'agent'}) as any;assert.match(adopted.prompt,/Verify CSV encoding/);assert.ok(adopted.adoption.journalEntryId);assert.equal(adopted.adoption.selection,'auto');const current=f.controller.snapshot(f.ctx).adoptions as FrozenRun;assert.equal(blockedByFrozenScope(current,'write',{path:'other/file'},f.dir),true);assert.equal(blockedByFrozenScope(current,'bash'),true);const count=f.entries.length;assert.deepEqual(await f.controller.dispatch('use',request,f.ctx),adopted);assert.equal(f.entries.length,count);assert.equal(f.ctx.executionMode,'single');const h=f.controller.skillCatalog.head(a.id,f.ctx);await f.controller.dispatch('skill.update',{id:a.id,expectedRevision:h.revision,body:'New method only for later runs.',key:'v2'},f.ctx);assert.match((await f.controller.dispatch('use',request,f.ctx) as any).prompt,/Verify CSV encoding/);await f.controller.dispatch('select',{ids:['reviewer']},f.ctx);const second=f.controller.beginRun({...f.ctx,runId:'run-2'});await assert.rejects(f.controller.dispatch('use',{expertId:'implementer',runId:second.runId,catalogHash:second.hash},{...f.ctx,runId:'run-2'}),/明确选择/);}finally{f.close();}});

test('E21: uncertain journal does not return body; reconciliation uses the original canonical operation',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const run=f.controller.beginRun(f.ctx),request={expertId:'implementer',runId:run.runId,catalogHash:run.hash,skillIds:[a.id]},append=f.ctx.appendEntry;let writes=0;f.ctx.appendEntry=(type,data)=>{writes++;append(type,data);throw new Error('journal acknowledgement lost');};await assert.rejects(f.controller.dispatch('use',request,f.ctx),(e:any)=>e.code==='OPERATION_UNKNOWN');assert.equal(blockedByFrozenScope(f.controller.snapshot(f.ctx).adoptions as FrozenRun,'write',{path:'x'},f.dir),false);f.ctx.appendEntry=append;const result=await f.controller.dispatch('use',request,f.ctx) as any;assert.ok(result.adoption.journalEntryId);assert.equal(writes,1);const other=f.controller.beginRun({...f.ctx,runId:'run-unknown'});await assert.rejects(f.controller.dispatch('use',{expertId:'implementer',runId:other.runId,catalogHash:other.hash,skillIds:[a.id]},{...f.ctx,runId:'run-unknown',appendEntry:()=>undefined,findJournalEntry:()=>undefined}),(e:any)=>e.code==='OPERATION_UNKNOWN');}finally{f.close();}});

test('E13/E18: readonly projection drift rebuilds and precise source withdrawal blocks historical body',async()=>{const f=fixture();try{const a=await f.submit(),other=await f.submit({evidence:[],skillBody:{title:'Unrelated manual',applicability:'CSV import',body:'Keep unrelated work.'}});const view=await f.controller.dispatch('projection.rebuild',{},f.ctx) as {path:string;drift:boolean};const file=readdirSync(view.path).find(name=>name===`${digest(a.id).slice(0,24)}.md`)!;writeFileSync(join(view.path,file),'external override');const rebuilt=await f.controller.dispatch('projection.rebuild',{},f.ctx) as {drift:boolean};assert.equal(rebuilt.drift,true);assert.match(readFileSync(join(view.path,file),'utf8'),/Verify CSV/);assert.equal(f.controller.skillCatalog.version(a.id,1,f.ctx).body,'Verify CSV encoding and required column names before import.');await f.controller.dispatch('source.invalidate',{sessionId:'s',reason:'source deleted',key:'delete'},f.ctx);assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).status,'withdrawn');assert.equal(f.controller.skillCatalog.head(other.id,f.ctx).status,'candidate');await assert.rejects(f.controller.dispatch('skill.read',{id:a.id,version:1},f.ctx),(e:any)=>e.code==='SOURCE_UNAVAILABLE');}finally{f.close();}});

test('E09/E10/E11: independent trace growth works with Memory unavailable and deduplicates results',async()=>{const f=fixture();try{const input={runId:'source-run',taskResultVersion:1,taskResult:{status:'corrected',note:'encoding bug'},evidence:f.evidence};const queued=await f.controller.dispatch('taskTraceReady',input,{...f.ctx,origin:'plugin'}) as {jobId:string};assert.equal((await f.controller.dispatch('taskTraceReady',input,{...f.ctx,origin:'plugin'}) as any).jobId,queued.jobId);await assert.rejects(f.controller.dispatch('taskTraceReady',{...input,taskResult:{status:'corrected',note:'changed'}},{...f.ctx,origin:'plugin'}),/不同任务结果/);assert.equal(peekExpertLearningJob(f.dir)?.id,queued.jobId);const job=await f.drain(queued.jobId);assert.equal(job.state,'completed');assert.equal(f.calls(),1);assert.equal(f.controller.skillCatalog.head(job.candidateId!,f.ctx).status,'trial');assert.ok(job.budgetId);assert.notEqual(job.budgetId,job.sourceRunId);const missing=await f.controller.dispatch('taskTraceReady',{...input,runId:'success-without-check',taskResult:{status:'completed'}},{...f.ctx,origin:'plugin'}) as any;assert.equal(missing.status,'waiting_evidence');const checkQueued=await f.controller.dispatch('taskTraceReady',{...input,runId:'success-with-check',taskResult:{status:'completed'},evidence:[...f.evidence,f.check()]},{...f.ctx,origin:'plugin'}) as any;assert.equal(checkQueued.status,'queued');}finally{f.close();}});

test('E14/E15/E16/E17: independent hidden release requires strict improvement in both phases',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);await assert.rejects(f.validation(a.id,m=>{m.release[0].families=m.validation[0].families;}),/泄漏/);await assert.rejects(f.validation(a.id,m=>{m.release[0].input=m.validation[0].input+'!';}),/泄漏/);await assert.rejects(f.validation(a.id,m=>{m.release.pop();}),/独立正例/);const scheduled=await f.validation(a.id);f.ctx.complete=async prompt=>JSON.stringify({ok:prompt.includes('Verify CSV encoding')});const job=await f.drain(scheduled.jobId);assert.equal(job.state,'completed');assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).validationKind,'growth');assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).status,'validated');const result=await f.controller.dispatch('validation.read',{jobId:job.id},f.ctx) as any;assert.equal(result.phases.length,2);assert.ok(result.phases.every((phase:any)=>phase.strictImprovement));assert.ok(!JSON.stringify(result).includes('scenario alpha'));assert.ok(!JSON.stringify(f.controller.snapshot(f.ctx)).includes('outside scope number seven'));}finally{f.close();}});

test('E14/E17: baseline also passing and critical regressions remain trial; rubric cannot override',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const scheduled=await f.validation(a.id);f.ctx.complete=async()=>'{"ok":true}';const job=await f.drain(scheduled.jobId);assert.equal(job.state,'waiting_evidence');assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).status,'trial');const b=await f.submit({skillBody:{title:'CSV critical regression',applicability:'CSV import',body:'Verify CSV encoding and required column names before import.'}});await f.trial(b.id,b.revision);const second=await f.validation(b.id);f.ctx.complete=async prompt=>prompt.includes('scenario beta')?'{"ok":false}':JSON.stringify({ok:prompt.includes('Verify CSV encoding')});const failed=await f.drain(second.jobId);assert.equal(failed.state,'waiting_evidence');assert.equal(f.controller.skillCatalog.head(b.id,f.ctx).status,'trial');assert.equal(f.controller.store.get(`evaluation:${second.jobId}`),undefined);}finally{f.close();}});

test('E19/E20: in-flight call finishes, next admission waits, and an unknown call never replays after cold start',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const scheduled=await f.validation(a.id);let resolve!:(value:string)=>void,started=false,count=0;f.ctx.complete=async()=>{count++;started=true;return await new Promise<string>(done=>{resolve=done;});};const pending=f.step(scheduled.jobId);while(!started)await new Promise(done=>setTimeout(done,1));f.admit(false);resolve('{"ok":false}');assert.equal((await pending).state,'queued');await f.step(scheduled.jobId);assert.equal(count,1);f.admit(true);f.ctx.complete=async()=>{count++;throw new CapabilityError('OPERATION_UNKNOWN','remote result unknown');};const unknown=await f.step(scheduled.jobId);assert.equal(unknown.unknown,true);assert.equal(unknown.state,'waiting_evidence');const reopened=new ExpertController(f.dir);try{assert.equal(reopened.store.get<ExpertLearningJob>(`job:${scheduled.jobId}`)!.value.unknown,true);await reopened.executeLearningJob(scheduled.jobId,f.ctx,{lease:f.lease});assert.equal(count,2);}finally{reopened.dispose();}const other=acquireLearningLease(f.controller.store,'second-host');assert.equal(other,undefined);}finally{f.close();}});

test('E18/E20: late validation response cannot publish after source invalidation or lease epoch change',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const scheduled=await f.validation(a.id);let resolve!:(value:string)=>void;f.ctx.complete=async()=>await new Promise<string>(done=>{resolve=done;});const pending=f.step(scheduled.jobId);while(!resolve)await new Promise(done=>setTimeout(done,1));await f.controller.dispatch('source.invalidate',{refs:[f.source],reason:'user correction',key:'correction'},f.ctx);resolve('{"ok":true}');assert.equal((await pending).state,'failed');assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).status,'withdrawn');assert.equal(f.controller.store.get(`evaluation:${scheduled.jobId}`),undefined);}finally{f.close();}});

test('E24: trial CAS reserves at most three tasks and a real failed check freezes future adoption',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);for(let i=1;i<=3;i++){const ctx={...f.ctx,runId:`trial-${i}`,taskId:`task-${i}`,history:()=>[{...f.ctx.history()[0],id:`independent-${i}`,text:`independent input ${i}`}]},run=f.controller.beginRun(ctx);await f.controller.dispatch('use',{expertId:'implementer',skillIds:[a.id],runId:run.runId,catalogHash:run.hash},ctx);}assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).trial!.reservedTasks,3);const ctx={...f.ctx,runId:'trial-4',taskId:'task-4',history:()=>[{...f.ctx.history()[0],id:'independent-4',text:'independent input 4'}]},run=f.controller.beginRun(ctx);await assert.rejects(f.controller.dispatch('use',{expertId:'implementer',skillIds:[a.id],runId:run.runId,catalogHash:run.hash},ctx),(e:any)=>e.code==='BUDGET_EXHAUSTED');const result=await f.controller.dispatch('trial.result',{id:a.id,taskId:'task-1',passed:false,objective:true,evidence:[f.check(false,'trial-1','task-1')],key:'failed'},{...f.ctx,origin:'plugin'}) as any;assert.equal(result.trial.frozen,true);assert.equal(f.controller.freeze({roleId:'reviewer'},f.ctx).role!.independent,false);}finally{f.close();}});

test('E22: legacy publication migrates to bounded partial trial, preserving IDs and old snapshots',async()=>{const f=fixture();try{f.controller.store.put('candidate:p:old',{id:'old',title:'Legacy method',method:'Check CSV encoding.',scope:'p',status:'published',sourceMemoryIds:[],sources:[f.source],checks:[],evaluation:{suiteHash:'old',cases:[{id:'a'}]},publishedId:'learned-old'},null);f.controller.store.remove('migration:skills:p');const snapshot=f.controller.snapshot(f.ctx),migrated=snapshot.skills.find(v=>v.id==='legacy-candidate.old')!;assert.equal(migrated.head.status,'trial');assert.equal(migrated.head.validationKind,'legacy-partial');assert.equal(migrated.head.trial?.maxTasks,3);assert.equal(f.controller.skillCatalog.version(migrated.id,1,f.ctx).legacy?.id,'old');const again=new ExpertController(f.dir);try{assert.equal(again.snapshot(f.ctx).skills.filter(v=>v.id===migrated.id).length,1);}finally{again.dispose();}}finally{f.close();}});

test('member adoption requires trusted identity and canonical journal before any body response',async()=>{const f=fixture();try{const catalog=await f.controller.dispatch('freeze',{catalog:true},f.ctx) as FrozenRun;const input={catalogHash:catalog.hash,id:'implementer',memberId:'member-1',attemptId:'attempt-1'};await assert.rejects(f.controller.dispatch('adopt.frozen',input,{...f.ctx,origin:'plugin'}),(e:any)=>e.code==='PERMISSION_DENIED');const ctx={...f.ctx,origin:'plugin' as const,memberId:'member-1',runId:'attempt-1',taskId:'task-1'},prepared=await f.controller.dispatch('adopt.frozen',input,ctx) as any;assert.equal(prepared.prompt,undefined);assert.equal(prepared.journalRequired,true);assert.ok(prepared.dependencyRefs.length>=4);await assert.rejects(f.controller.dispatch('adopt.confirm',{operationId:prepared.adoption.operationId,catalogHash:catalog.hash,id:'implementer'},ctx),(e:any)=>e.code==='OPERATION_UNKNOWN');ctx.appendEntry('friend-pi.expert.adoption',prepared.adoption);const confirmed=await f.controller.dispatch('adopt.confirm',{operationId:prepared.adoption.operationId,catalogHash:catalog.hash,id:'implementer'},ctx) as any;assert.ok(confirmed.prompt);assert.ok(confirmed.adoption.journalEntryId);}finally{f.close();}});

test('E22: legacy SQLite writer cannot change a migrated Skill head',async()=>{const f=fixture();try{const created=await f.submit();f.controller.snapshot(f.ctx);const before=f.controller.skillCatalog.head(created.id,f.ctx),old=new DatabaseSync(join(f.dir,'plugins.sqlite'));try{assert.throws(()=>old.prepare("UPDATE documents SET json=? WHERE namespace='expert' AND key=?").run(JSON.stringify({...before,status:'validated'}),`skill.head:p:${created.id}`),/friend_pi_writer_version|schema writer/i);assert.deepEqual(f.controller.skillCatalog.head(created.id,f.ctx),before);assert.ok(old.prepare("SELECT json FROM documents WHERE namespace='expert' AND key=?").get(`skill.head:p:${created.id}`));}finally{old.close();}}finally{f.close();}});

test('E18: Memory dependency withdrawal affects only actual dependents and never bans independently valid Pi evidence',async()=>{const f=fixture();try{const dependency={capability:'memory' as const,id:'m',version:1,hash:digest('memory'),relation:'derived-from' as const};f.policy.publishDependency({...dependency,projectId:'p',valid:true});const a=await f.submit({evidence:[...f.evidence,{kind:'memory',projectId:'p',dependency,sources:[f.source],artifacts:[],observationReceiptIds:[]}]}),b=await f.submit({skillBody:{title:'Independent Pi method',applicability:'CSV import',body:'Verify CSV against the independent source.'}});await f.controller.dispatch('source.invalidate',{dependencies:[dependency],refs:[],reason:'memory forgotten',key:'forget-memory'},f.ctx);assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).status,'withdrawn');assert.equal(f.controller.skillCatalog.head(b.id,f.ctx).status,'candidate');assert.match((await f.controller.dispatch('skill.read',{id:b.id,version:1},f.ctx) as any).body,/Verify CSV/);}finally{f.close();}});

test('E20: a late former lease owner cannot save a validation response',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const scheduled=await f.validation(a.id);let resolve!:(value:string)=>void;f.ctx.complete=async()=>await new Promise<string>(done=>{resolve=done;});const pending=f.step(scheduled.jobId);while(!resolve)await new Promise(done=>setTimeout(done,1));releaseLearningLease(f.controller.store,f.lease);const next=acquireLearningLease(f.controller.store,'replacement-host')!;assert.ok(next.epoch>f.lease.epoch);resolve('{"ok":true}');assert.equal((await pending).state,'failed');assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).status,'trial');assert.equal(f.controller.store.list(`evaluation.pair:${scheduled.jobId}:`).length,0);releaseLearningLease(f.controller.store,next);}finally{f.close();}});

test('E19/E20: confirmed transient failures retry at most three times with distinct accounted calls',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const scheduled=await f.validation(a.id),budget=new LearningBudget(f.controller.store);let count=0;f.ctx.complete=async(prompt,options)=>{count++;const call=budget.begin({budgetId:options!.budgetId!,operationId:options!.operationId!,callId:options!.callId,stage:options!.stage,promptHash:digest(prompt)});budget.finish({budgetId:options!.budgetId!,operationId:options!.operationId!,callId:call.callId,tokens:0,state:'failed'});throw new CapabilityError('VALIDATION_ERROR','confirmed transient fixture failure');};assert.equal((await f.step(scheduled.jobId)).state,'retryable');assert.equal((await f.step(scheduled.jobId)).state,'retryable');const final=await f.step(scheduled.jobId);assert.equal(final.state,'failed');assert.equal(count,3);assert.equal(budget.read(final.budgetId).calls,3);assert.equal(final.unknown,undefined);}finally{f.close();}});

test('method observation receipts distinguish selected content from the observed provider payload',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const run=f.controller.beginRun(f.ctx),adopted=await f.controller.dispatch('use',{expertId:'implementer',skillIds:[a.id],runId:run.runId,catalogHash:run.hash},f.ctx) as any;assert.deepEqual(f.controller.observePrepared({messages:[{content:'metadata only'}]},f.ctx),[]);const observed=f.controller.observePrepared({messages:[{content:adopted.prompt}]},f.ctx);assert.equal(observed.length,1);assert.equal(observed[0].stage,'request-prepared');assert.equal(observed[0].contentHash,digest(f.controller.skillCatalog.version(a.id,1,f.ctx).body));assert.deepEqual(observed[0].visibleRanges,[[0,f.controller.skillCatalog.version(a.id,1,f.ctx).body.length]]);assert.equal(observed[0].observer?.kind,'foreground');}finally{f.close();}});

test('growth creates an immutable next version, rejects stale parents, deduplicates exact content and never relaxes restrictions',async()=>{const f=fixture();try{const a=await f.submit({skillBody:{title:'Restricted method',applicability:'CSV import',body:'Read CSV encoding.',restrictions:{tools:['read'],writeScopes:[]}}});const input={id:a.id,baseVersion:1,key:'growth-2',skillBody:{title:'Restricted method',applicability:'CSV import',body:'Read CSV encoding and column names.',restrictions:{tools:['write'],writeScopes:['.']}},evidence:f.evidence};const next=await f.controller.dispatch('candidate.submit',input,{...f.ctx,origin:'plugin'}) as any;assert.equal(next.version,2);assert.equal(f.controller.skillCatalog.version(a.id,1,f.ctx).body,'Read CSV encoding.');assert.deepEqual(f.controller.skillCatalog.version(a.id,2,f.ctx).restrictions,{tools:[],writeScopes:[]});await assert.rejects(f.controller.dispatch('candidate.submit',{...input,key:'stale'},{...f.ctx,origin:'plugin'}),/baseVersion/);const duplicate=await f.controller.dispatch('candidate.submit',{...input,baseVersion:2,key:'same-content'},{...f.ctx,origin:'plugin'}) as any;assert.equal(duplicate.version,2);assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).version,2);}finally{f.close();}});


test('new runs keep stable methods while an explicit trial pins the candidate version',async()=>{const f=fixture();try{const id='seed.implementer.1',old=f.controller.beginRun(f.ctx),oldSkill=old.experts.find(expert=>expert.id==='implementer')!.frozenSkills!.find(skill=>skill.id===id)!;assert.equal(oldSkill.version,1);const head=f.controller.skillCatalog.head(id,f.ctx),edited=await f.controller.dispatch('skill.update',{id,expectedRevision:head.revision,body:'A project method with corrected implementation checks.',key:'seed-edit'},f.ctx) as {revision:number;version:number};const changed=f.controller.skillCatalog.version(id,edited.version,f.ctx);await f.controller.dispatch('trial.configure',{id,expectedRevision:edited.revision,scope:{projectId:f.ctx.projectId,applicability:changed.applicability},limits:{maxTasks:3},key:'seed-trial'},f.ctx);const continued=f.controller.beginRun(f.ctx);assert.equal(continued.hash,old.hash);assert.equal(continued.experts.find(expert=>expert.id==='implementer')!.frozenSkills!.find(skill=>skill.id===id)!.body,oldSkill.body);const ctx={...f.ctx,runId:'new-run',policy:{...f.ctx.policy!,runId:'new-run'}},next=f.controller.beginRun(ctx),newSkill=next.experts.find(expert=>expert.id==='implementer')!.frozenSkills!.find(skill=>skill.id===id)!;assert.equal(newSkill.version,1);assert.equal(newSkill.body,oldSkill.body);assert.ok(next.availableSkills!.some(skill=>skill.id===id&&skill.version===2&&skill.statusAtFreeze==='trial'));assert.notEqual(next.hash,old.hash);const adopted=await f.controller.dispatch('use',{expertId:'implementer',runId:next.runId,catalogHash:next.hash},ctx) as {prompt:string};assert.match(adopted.prompt,new RegExp(oldSkill.body.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')));const explicit=await f.controller.dispatch('use',{expertId:'implementer',runId:next.runId,catalogHash:next.hash,skillIds:[id],skillRefs:[{id,version:2}]},ctx) as {prompt:string};assert.match(explicit.prompt,/corrected implementation checks/);assert.equal(old.experts.find(expert=>expert.id==='implementer')!.frozenSkills!.find(skill=>skill.id===id)!.body,oldSkill.body);const pinned=await f.controller.dispatch('freeze',{expertId:'implementer',skillRefs:[{id,version:1}]},ctx) as FrozenRun;assert.equal(pinned.experts[0].frozenSkills![0].body,oldSkill.body);await assert.rejects(f.controller.dispatch('freeze',{expertId:'implementer',skillRefs:[{id,version:1}]},{...ctx,origin:'agent'}),/用户/);}finally{f.close();}});

test('native authority admits only actual available tools and unknown authority remains deny-all',async()=>{const f=fixture();try{for(const [runId,availableTools,expected] of [['native-authority',['read','friend_expert'],['read','friend_expert']],['unknown-authority',undefined,[]]] as const){const ctx={...f.ctx,runId,policy:undefined,availableTools:availableTools?[...availableTools]:undefined},run=f.controller.beginRun(ctx),adopted=await f.controller.dispatch('use',{expertId:'implementer',runId:run.runId,catalogHash:run.hash},ctx) as {toolScope:string[]};assert.deepEqual(adopted.toolScope,expected);assert.equal(blockedByFrozenScope(f.controller.snapshot(ctx).adoptions as FrozenRun,'write',{path:'file'},f.dir),true);assert.equal(blockedByFrozenScope(f.controller.snapshot(ctx).adoptions as FrozenRun,'read',{path:'file'},f.dir),availableTools===undefined);}}finally{f.close();}});

test('extract exposes only mutable project bases; a seed-only catalog produces a new method',async()=>{const f=fixture();try{let catalog:any;f.ctx.complete=async prompt=>{catalog=JSON.parse(prompt.split('只读项目目录：')[1].split('。任务结果：')[0]);assert.match(prompt,/不得引用内置Skill或捏造基线/);return JSON.stringify({title:'CSV new method',applicability:'CSV import',body:'Verify CSV encoding before import.'});};const queued=await f.controller.dispatch('taskTraceReady',{runId:'seed-only',taskResultVersion:1,taskResult:{status:'corrected'},evidence:f.evidence},{...f.ctx,origin:'plugin'}) as {jobId:string},job=await f.step(queued.jobId);assert.deepEqual(catalog.items,[]);assert.equal(job.state,'completed');assert.equal(f.controller.skillCatalog.head(job.candidateId!,f.ctx).scope,'project');assert.ok(!job.candidateId!.startsWith('seed.'));assert.equal(f.controller.skillCatalog.head('seed.planner.3',f.ctx).scope,'builtin');}finally{f.close();}});

test('extract can CAS-grow a visible project head while keeping the previous version immutable',async()=>{const f=fixture();try{const skill=await f.submit();await f.trial(skill.id,skill.revision);f.ctx.complete=async prompt=>{const catalog=JSON.parse(prompt.split('只读项目目录：')[1].split('。任务结果：')[0]);assert.equal(catalog.items.length,1);assert.equal(catalog.items[0].scope,'project');assert.equal(catalog.items[0].id,skill.id);return JSON.stringify({title:'CSV preflight',applicability:'CSV import',body:'Verify CSV encoding and required columns, then report the actual errors.',baseSkillId:skill.id,baseVersion:catalog.items[0].version});};const queued=await f.controller.dispatch('taskTraceReady',{runId:'project-growth',taskResultVersion:1,taskResult:{status:'corrected'},evidence:f.evidence},{...f.ctx,origin:'plugin'}) as {jobId:string},job=await f.step(queued.jobId);assert.equal(job.state,'completed');assert.equal(job.candidateId,skill.id);assert.equal(f.controller.skillCatalog.head(skill.id,f.ctx).version,2);assert.equal(f.controller.skillCatalog.version(skill.id,1,f.ctx).body,'Verify CSV encoding and required column names before import.');assert.match(f.controller.skillCatalog.version(skill.id,2,f.ctx).body,/actual errors/);}finally{f.close();}});

test('invented extract bases retry at most three metered calls and cannot alter a builtin',async()=>{const f=fixture();try{const budget=new LearningBudget(f.controller.store),operations=new Set<string>();let count=0;f.ctx.complete=async(prompt,options)=>{count++;operations.add(options!.operationId!);const output=JSON.stringify({title:'Forged baseline',applicability:'CSV import',body:'Verify CSV encoding.',baseSkillId:'seed.planner.3',baseVersion:1}),call=budget.begin({budgetId:options!.budgetId!,operationId:options!.operationId!,callId:options!.callId,stage:options!.stage,promptHash:digest(prompt)});budget.finish({budgetId:options!.budgetId!,operationId:options!.operationId!,callId:call.callId,result:output,tokens:1,state:'complete'});return output;};const queued=await f.controller.dispatch('taskTraceReady',{runId:'invented-base',taskResultVersion:1,taskResult:{status:'corrected'},evidence:f.evidence},{...f.ctx,origin:'plugin'}) as {jobId:string};assert.equal((await f.step(queued.jobId)).state,'retryable');assert.equal((await f.step(queued.jobId)).state,'retryable');const failed=await f.step(queued.jobId);assert.equal(failed.state,'failed');assert.equal(failed.attempts,3);assert.match(failed.error!,/^VALIDATION_ERROR:/);assert.equal(failed.unknown,undefined);await f.step(queued.jobId);assert.equal(count,3);assert.equal(operations.size,3);assert.equal(budget.read(failed.budgetId).calls,3);assert.equal(f.controller.skillCatalog.head('seed.planner.3',f.ctx).scope,'builtin');assert.equal(f.controller.skillCatalog.head('seed.planner.3',f.ctx).version,1);}finally{f.close();}});

test('a project head changed during extract keeps the actual VERSION_CONFLICT and never overwrites the concurrent edit',async()=>{const f=fixture();try{const skill=await f.submit();await f.trial(skill.id,skill.revision);f.ctx.complete=async prompt=>{const catalog=JSON.parse(prompt.split('只读项目目录：')[1].split('。任务结果：')[0]),base=catalog.items.find((entry:any)=>entry.id===skill.id);assert.ok(base);const head=f.controller.skillCatalog.head(skill.id,f.ctx);await f.controller.dispatch('skill.update',{id:skill.id,expectedRevision:head.revision,body:'Concurrent user correction.',key:'concurrent-edit'},f.ctx);return JSON.stringify({title:'CSV preflight',applicability:'CSV import',body:'A stale generated correction.',baseSkillId:base.id,baseVersion:base.version});};const queued=await f.controller.dispatch('taskTraceReady',{runId:'concurrent-base',taskResultVersion:1,taskResult:{status:'corrected'},evidence:f.evidence},{...f.ctx,origin:'plugin'}) as {jobId:string},failed=await f.step(queued.jobId);assert.equal(failed.state,'failed');assert.match(failed.error!,/^VERSION_CONFLICT:/);assert.equal(f.controller.skillCatalog.head(skill.id,f.ctx).version,2);assert.equal(f.controller.skillCatalog.version(skill.id,2,f.ctx).body,'Concurrent user correction.');}finally{f.close();}});

test('trial.observe binds canonical adoption version and real run/task checks; duplicates count once and a later failed check freezes',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const ctx={...f.ctx,runId:'trial-production',taskId:'bound-task',policy:{...f.ctx.policy!,runId:'trial-production'}},run=f.controller.beginRun(ctx);await f.controller.dispatch('use',{expertId:'implementer',runId:run.runId,catalogHash:run.hash,skillIds:[a.id]},ctx);const good=f.check(true,ctx.runId,ctx.taskId),input={runId:ctx.runId,taskId:ctx.taskId,checks:[good.check],outcome:'completed',key:'actual-check-1'},host={...ctx,origin:'plugin' as const};await assert.rejects(f.controller.dispatch('trial.observe',{...input,checks:[f.check(true,'another-run','another-task').check]},host),(e:any)=>e.code==='PERMISSION_DENIED');await assert.rejects(f.controller.dispatch('trial.observe',input,{...ctx,origin:'agent'}),(e:any)=>e.code==='PERMISSION_DENIED');const result=await f.controller.dispatch('trial.observe',input,host) as any;assert.equal(result.settled.length,1);assert.equal(f.controller.skillCatalog.head(a.id,ctx).trial!.completedTasks,1);await f.controller.dispatch('trial.observe',input,host);assert.equal(f.controller.skillCatalog.head(a.id,ctx).trial!.completedTasks,1);await f.controller.dispatch('trial.observe',{...input,key:'actual-check-2',checks:[f.check(false,ctx.runId,ctx.taskId).check],outcome:'failed'},host);assert.equal(f.controller.skillCatalog.head(a.id,ctx).trial!.frozen,true);const h=f.controller.skillCatalog.head(a.id,ctx),v2=await f.controller.dispatch('skill.update',{id:a.id,expectedRevision:h.revision,body:'A corrected version for a new trial.',key:'correct-v2'},f.ctx) as {revision:number};await f.trial(a.id,v2.revision);await assert.rejects(f.controller.dispatch('trial.result',{id:a.id,version:1,taskId:ctx.taskId,passed:false,objective:true,evidence:[f.check(false,ctx.runId,ctx.taskId)],key:'old-version'},host),(e:any)=>e.code==='VERSION_CONFLICT');await f.controller.dispatch('trial.observe',{...input,key:'late-v1',checks:[f.check(false,ctx.runId,ctx.taskId).check],outcome:'failed'},host);assert.equal(f.controller.skillCatalog.head(a.id,ctx).trial!.frozen,undefined);}finally{f.close();}});

test('same method with supplementary evidence preserves version, trial quota and failure freeze',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const ctx={...f.ctx,runId:'frozen-trial',policy:{...f.ctx.policy!,runId:'frozen-trial'}},run=f.controller.beginRun(ctx);await f.controller.dispatch('use',{expertId:'implementer',runId:run.runId,catalogHash:run.hash,skillIds:[a.id]},ctx);await f.controller.dispatch('trial.observe',{runId:ctx.runId,checks:[f.check(false,ctx.runId,'check-task').check],outcome:'failed',key:'failed-trial'},{...ctx,origin:'plugin'});const before=f.controller.skillCatalog.head(a.id,ctx),version=f.controller.skillCatalog.version(a.id,1,ctx),body={title:version.title,description:version.description,keywords:version.keywords,applicability:version.applicability,exclusions:version.exclusions,body:version.body};const same=await f.submit({id:a.id,baseVersion:1,skillBody:body,evidence:[...f.evidence,f.check(true)]});assert.equal(same.id,a.id);assert.deepEqual(f.controller.skillCatalog.head(a.id,ctx),before);const duplicate=await f.submit({skillBody:body,evidence:[...f.evidence,f.check(true)]});assert.equal(duplicate.id,a.id);assert.deepEqual(f.controller.skillCatalog.head(a.id,ctx),before);assert.ok(f.controller.store.list(`skill.evidence:${ctx.projectId}:${a.id}:1:`).length>0);}finally{f.close();}});

test('explicit main selection applies project Skill restrictions before the first injected prompt',async()=>{const f=fixture();try{const a=await f.submit({id:'seed.implementer.1',evidence:[],skillBody:{title:'Restricted implementer',applicability:'implementation',body:'Read source only.',restrictions:{tools:['read'],writeScopes:[]}}});await f.controller.dispatch('trial.configure',{id:a.id,expectedRevision:a.revision,scope:{projectId:'p',applicability:'implementation'},limits:{maxTasks:3},key:'restricted-trial'},f.ctx);await f.controller.dispatch('select',{ids:['implementer'],skillRefs:[{id:a.id,version:f.controller.skillCatalog.head(a.id,f.ctx).version}]},f.ctx);const run=f.controller.beginRun(f.ctx);assert.deepEqual(run.toolScope,['read']);assert.deepEqual(run.effectiveWriteScopes,[]);assert.match(run.prompt,/Read source only/);assert.equal(blockedByFrozenScope(run,'write',{path:'out'},f.dir),true);assert.equal(blockedByFrozenScope(run,'read',{path:'out'},f.dir),false);assert.ok(f.controller.store.list<any>('adoption.receipt:').every(row=>row.value.journalEntryId));}finally{f.close();}});

function actualTrialCheck(f:ReturnType<typeof fixture>,runId:string,taskId:string,exitCode:number,trialAttribution:unknown=f.attribution(runId)){const result=spawnSync(process.execPath,['-e',`process.exit(${exitCode})`],{encoding:'utf8'});assert.equal(result.status,exitCode);const check={checkId:randomUUID(),version:1,hash:digest({runId,taskId,exitCode:result.status}),taskId,producerRunId:runId,artifacts:[]};f.policy.registerCheck({ref:check,projectId:f.ctx.projectId,passed:result.status===0,output:{exitCode:result.status,stdout:result.stdout,stderr:result.stderr,...(trialAttribution===null?{}:{trialAttribution})},sources:[f.source]});return check;}
async function adoptTrialRun(f:ReturnType<typeof fixture>,id:string,runId:string,taskId:string,input:string){const ctx={...f.ctx,runId,taskId,policy:{...f.ctx.policy!,runId},history:()=>[{...f.ctx.history()[0],text:input}]},run=f.controller.beginRun(ctx);await f.controller.dispatch('use',{expertId:'implementer',runId,catalogHash:run.hash,skillIds:[id]},ctx);return {...ctx,origin:'plugin' as const};}

test('a repeated logical task keeps each run binding; a new run actual failure freezes without spending another trial',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const taskId='same-logical-task',first=await adoptTrialRun(f,a.id,'run-A',taskId,'first task input');await f.controller.dispatch('trial.observe',{runId:first.runId,taskId,checks:[actualTrialCheck(f,first.runId,taskId,0)],outcome:'completed',key:'same-check-revision'},first);const second=await adoptTrialRun(f,a.id,'run-B',taskId,'revised input for the same task'),result=await f.controller.dispatch('trial.observe',{runId:second.runId,taskId,checks:[actualTrialCheck(f,second.runId,taskId,1)],outcome:'failed',key:'same-check-revision'},second) as any;assert.equal(result.settled.length,1);const head=f.controller.skillCatalog.head(a.id,f.ctx);assert.equal(head.trial!.reservedTasks,1);assert.equal(head.trial!.completedTasks,1);assert.equal(head.trial!.frozen,true);const rows=f.controller.store.list<any>(`trial.reservation:${f.ctx.projectId}:${a.id}:1:`).map(row=>row.value);assert.equal(rows.length,2);assert.equal(rows.find(row=>row.runId==='run-A').passed,true);assert.equal(rows.find(row=>row.runId==='run-B').passed,false);assert.equal(new Set(rows.map(row=>row.quotaKey)).size,1);}finally{f.close();}});

test('cross-run repeated successes and repeated inputs count once while independent task quota remains bounded',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);for(const [runId,taskId,input] of [['A','logical-A','input-A'],['B','logical-A','revised-A'],['C','logical-C','input-A'],['D','logical-D','input-D'],['E','logical-E','input-E']]){const ctx=await adoptTrialRun(f,a.id,runId,taskId,input);await f.controller.dispatch('trial.observe',{runId,taskId,checks:[actualTrialCheck(f,runId,taskId,0)],outcome:'completed',key:'same-success-event'},ctx);}const h=f.controller.skillCatalog.head(a.id,f.ctx);assert.equal(h.trial!.reservedTasks,3);assert.equal(h.trial!.completedTasks,3);assert.equal(h.trial!.waitingReason,'waiting_evidence');await assert.rejects(adoptTrialRun(f,a.id,'F','logical-F','input-F'),(e:any)=>e.code==='BUDGET_EXHAUSTED');await adoptTrialRun(f,a.id,'retry-A','logical-A','a later input for the same logical task');assert.equal(f.controller.skillCatalog.head(a.id,f.ctx).trial!.reservedTasks,3);}finally{f.close();}});

test('late old-run failures retain their binding and cannot freeze a new Skill version for the same task',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const taskId='same-task',old=await adoptTrialRun(f,a.id,'old-run',taskId,'old input'),h=f.controller.skillCatalog.head(a.id,f.ctx),updated=await f.controller.dispatch('skill.update',{id:a.id,expectedRevision:h.revision,body:'A corrected method for the next version.',key:'correct-after-adoption'},f.ctx) as {revision:number};await f.trial(a.id,updated.revision);const current=await adoptTrialRun(f,a.id,'new-run',taskId,'new input'),failed=actualTrialCheck(f,old.runId,taskId,1),late=await f.controller.dispatch('trial.observe',{runId:old.runId,taskId,checks:[failed],outcome:'failed',key:'late-old-check'},old) as any;assert.deepEqual(late.settled,[]);await assert.rejects(f.controller.dispatch('trial.result',{id:a.id,version:1,runId:old.runId,taskId,passed:false,objective:true,evidence:[{kind:'check',projectId:f.ctx.projectId,check:failed}],key:'explicit-late-old-check'},old),(e:any)=>e.code==='VERSION_CONFLICT');await f.controller.dispatch('trial.observe',{runId:current.runId,taskId,checks:[actualTrialCheck(f,current.runId,taskId,0)],outcome:'completed',key:'new-version-check'},current);const head=f.controller.skillCatalog.head(a.id,f.ctx);assert.equal(head.version,2);assert.equal(head.trial!.reservedTasks,1);assert.equal(head.trial!.completedTasks,1);assert.equal(head.trial!.frozen,undefined);assert.equal(f.controller.store.list<any>(`trial.reservation:${f.ctx.projectId}:${a.id}:1:`)[0].value.runId,old.runId);}finally{f.close();}});

test('one member canonical receipt cannot settle another member binding in the same run and task',async()=>{const f=fixture();try{const a=await f.submit({id:'seed.implementer.1',skillBody:{title:'Bound member method',applicability:'CSV import',body:'Check current CSV encoding.'}});await f.trial(a.id,a.revision);const catalog=await f.controller.dispatch('freeze',{catalog:true,expertId:'implementer',skillRefs:[{id:a.id,version:2}]},f.ctx) as FrozenRun,base={...f.ctx,origin:'plugin' as const,runId:'same-member-run',taskId:'same-member-task',inputHash:digest('the current member input'),taskScope:digest('the current graph')},first={...base,memberId:'member-A'},second={...base,memberId:'member-B'},prepare=async(ctx:typeof first)=>await f.controller.dispatch('adopt.frozen',{catalogHash:catalog.hash,id:'implementer',memberId:ctx.memberId,attemptId:ctx.runId},ctx) as any;const confirmed=await prepare(first);f.ctx.appendEntry('friend-pi.expert.adoption',confirmed.adoption);await f.controller.dispatch('adopt.confirm',{operationId:confirmed.adoption.operationId,catalogHash:catalog.hash,id:'implementer'},first);await prepare(second);const check=actualTrialCheck(f,base.runId,base.taskId,0),result=await f.controller.dispatch('trial.observe',{runId:base.runId,taskId:base.taskId,checks:[check],outcome:'completed',key:'member-check'},base) as any;assert.equal(result.settled.length,1);const rows=f.controller.store.list<any>(`trial.reservation:${f.ctx.projectId}:${a.id}:2:`).map(row=>row.value);assert.equal(rows.find(row=>row.memberId==='member-A').status,'completed');assert.equal(rows.find(row=>row.memberId==='member-B').status,'reserved');await assert.rejects(f.controller.dispatch('trial.result',{id:a.id,runId:base.runId,memberId:'member-B',taskId:base.taskId,passed:true,objective:true,evidence:[{kind:'check',projectId:f.ctx.projectId,check}],key:'unconfirmed-member'},base),(e:any)=>e.code==='OPERATION_UNKNOWN');}finally{f.close();}});

async function adoptMemberTrialInput(f:ReturnType<typeof fixture>,catalog:FrozenRun,memberId:string,runId:string,taskId:string,inputHash:string,taskScope=digest('shared-member-graph')){const ctx={...f.ctx,origin:'plugin' as const,memberId,runId,taskId,inputHash,taskScope},prepared=await f.controller.dispatch('adopt.frozen',{catalogHash:catalog.hash,id:'implementer',memberId,attemptId:runId},ctx) as any;f.ctx.appendEntry('friend-pi.expert.adoption',prepared.adoption);await f.controller.dispatch('adopt.confirm',{operationId:prepared.adoption.operationId,catalogHash:catalog.hash,id:'implementer'},ctx);return ctx;}
