test('EX01: unchanged startup reuses directory rows and incremental versions equal a full rebuild',async()=>{const f=fixture();try{const a=await f.submit();await f.trial(a.id,a.revision);const sql='SELECT rowid,* FROM expert_skill_directory ORDER BY projectId,skillId,version',before=f.controller.store.db.prepare(sql).all();const reopened=new ExpertController(f.dir);try{assert.deepEqual(reopened.store.db.prepare(sql).all(),before);const v=await f.controller.dispatch('skill.update',{id:a.id,expectedRevision:f.controller.skillCatalog.head(a.id,f.ctx).revision,body:'A changed encoding method.',key:'incremental-index'},f.ctx) as {revision:number};await f.trial(a.id,v.revision);const incremental=f.controller.store.db.prepare('SELECT * FROM expert_skill_directory ORDER BY projectId,skillId,version').all(),deps=f.controller.store.db.prepare('SELECT * FROM expert_source_dependencies ORDER BY projectId,sourceKey,dependentId,version').all(),hits=f.controller.skillCatalog.search({query:'编码'},f.ctx);f.controller.skillCatalog.rebuildIndex();assert.deepEqual(f.controller.store.db.prepare('SELECT * FROM expert_skill_directory ORDER BY projectId,skillId,version').all(),incremental);assert.deepEqual(f.controller.store.db.prepare('SELECT * FROM expert_source_dependencies ORDER BY projectId,sourceKey,dependentId,version').all(),deps);assert.deepEqual(f.controller.skillCatalog.search({query:'编码'},f.ctx),hits);}finally{reopened.dispose();}}finally{f.close();}});

